package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.notification.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/orchestrator/stage8/notifications") public class NotificationDeliveryController {private final NotificationDeliveryService service;public NotificationDeliveryController(NotificationDeliveryService service){this.service=service;}@PostMapping("/deliver") public NotificationDeliveryResult deliver(@RequestBody NotificationDeliveryRequest r){return service.deliver(r);}}
